<?php
/**
 * The card's icons.
 *
 * @package Baukasten\BusinessCards
 */

namespace Baukasten\BusinessCards;

defined( 'ABSPATH' ) || exit;

/**
 * Inline SVG glyphs, drawn or bundled here rather than fetched.
 *
 * Two sets. The interface glyphs — a handset, an envelope, a globe — are
 * outlines drawn for this plugin. The network marks are the networks' own
 * logos, because a button that says LinkedIn is recognised by its logo long
 * before its label is read. They are used unmodified, only to link to the
 * card holder's own profile, which is the use every one of these brands'
 * guidelines allows.
 *
 * Where the marks come from is written down because it matters for the licence:
 * LinkedIn, GitHub, Mastodon, Facebook, Instagram, Threads and Discord are the
 * paths WordPress core ships in its Social Links block (GPL, like this plugin);
 * core has no Xing and no Signal, so those two are from Simple Icons, which is
 * CC0. Nothing is loaded from either at runtime.
 *
 * Everything is a 24×24 viewBox painted in `currentColor`, so a card's palette
 * and its light and dark modes reach the icons without a second set of
 * variables. The marks are therefore one colour, the design's, rather than the
 * brands' — several of those are black and would vanish on a dark card.
 */
final class Icons {

	/**
	 * Renders one glyph.
	 *
	 * @param string $name Glyph name.
	 * @return string SVG markup, or an empty string when there is no such glyph.
	 */
	public static function get( string $name ): string {
		$paths = self::paths();

		if ( ! isset( $paths[ $name ] ) ) {
			return '';
		}

		return '<svg class="bkbc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'
			. $paths[ $name ]
			. '</svg>';
	}

	/**
	 * Renders one network's mark.
	 *
	 * Filled rather than stroked, which is how the marks are drawn; the interface
	 * glyphs above are outlines.
	 *
	 * @param string $network Network key, with or without the `network_` prefix.
	 * @return string SVG markup, or an empty string for a network without a mark.
	 */
	public static function brand( string $network ): string {
		$network = str_replace( 'network_', '', $network );
		$paths   = self::brands();

		if ( ! isset( $paths[ $network ] ) ) {
			return '';
		}

		/*
		 * Core's marks leave about two units of air inside the 24-unit box;
		 * Simple Icons, and core's own Mastodon, draw to the very edge. Side by
		 * side the edge-to-edge ones read a size larger and noticeably heavier — at
		 * 18px Signal's dotted ring closes up into a blob — so they get the same
		 * air through a wider viewBox rather than an edited path.
		 */
		$view_box = in_array( $network, array( 'mastodon', 'xing', 'signal' ), true ) ? '-2 -2 28 28' : '0 0 24 24';

		return '<svg class="bkbc-icon bkbc-icon--brand" viewBox="' . $view_box . '" fill="currentColor" aria-hidden="true" focusable="false"><path d="'
			. $paths[ $network ]
			. '"/></svg>';
	}

